:root {
  --bg: #0d1117;
  --panel: #141a23;
  --panel-2: #1a2230;
  --line: #252f3f;
  --line-2: #1c2431;
  --text: #e7ebf1;
  --muted: #8b96a7;
  --accent: #f0b84a;
  --cat: #6aa8ff;
  --gro: #3fc6a8;
  --age: #c79bff;
  --thin: #f08a7a;
  --tvl: #e7ebf1;
  --dur: #9fb0c6;
  --up: #3fc6a8;
  --down: #ef7d70;
  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 20px;
  /* type scale: hero 34, title 20, table 14, caption/chip 12 */
  --t-title: 20px;
  --t-section: 12px;
  --t-table: 14px;
  --t-cap: 12px;
  --mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
}
* { box-sizing: border-box; }
html, body { margin: 0; min-height: 100%; }
body {
  display: flex; flex-direction: column;
  background: var(--bg); color: var(--text);
  font: var(--t-table)/1.4 -apple-system, "Segoe UI", Inter, Roboto, "Helvetica Neue", Arial, sans-serif;
  font-variant-numeric: tabular-nums;
}
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
mark { background: rgba(240,184,74,.28); color: #fff; border-radius: 2px; padding: 0 1px; }

.top { display: flex; align-items: baseline; gap: var(--s4); padding: var(--s3) var(--s5) var(--s2); }
.brand { display: flex; align-items: center; gap: var(--s2); }
.dot { width: 10px; height: 10px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 4px rgba(240,184,74,.18); }
h1 { margin: 0; font-size: var(--t-title); font-weight: 650; letter-spacing: .01em; line-height: 1.2; }
.meta { margin: 0; color: var(--muted); font-size: var(--t-cap); }
.meta b { color: var(--text); font-weight: 600; }

.strip { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: var(--s2); margin: 0 var(--s5) var(--s2); }
.stat { display: flex; align-items: baseline; gap: var(--s2); padding: 6px var(--s3); background: var(--panel); border: 1px solid var(--line); border-radius: 8px; min-width: 0; }
.sk { font-size: var(--t-cap); color: var(--muted); text-transform: uppercase; letter-spacing: .06em; white-space: nowrap; }
.sv { font: 700 18px/1.2 var(--mono); color: var(--text); }
.stat.hero { padding: 8px var(--s4); border-color: rgba(240,184,74,.55); background: linear-gradient(180deg, #1c2431, var(--panel)); }
.stat.hero .sk { color: var(--text); }
.stat.hero .sv { font-size: 36px; line-height: 1; color: #ffd27a; letter-spacing: -.01em; }
.sc { margin-left: auto; font-size: var(--t-cap); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.legend { display: flex; align-items: center; flex-wrap: wrap; gap: var(--s1) var(--s4); margin: 0 var(--s5) var(--s2); padding: 6px var(--s3); background: var(--panel); border: 1px solid var(--line); border-radius: 8px; }
.formula { font: 600 var(--t-table) var(--mono); white-space: nowrap; }
.formula b { font-weight: 700; cursor: help; }
.c-cat { color: var(--cat); } .c-gro { color: var(--gro); } .c-age { color: var(--age); } .c-thin { color: var(--thin); }
.keys { display: flex; flex-wrap: wrap; gap: var(--s1) var(--s4); margin: 0 0 0 auto; color: var(--muted); font-size: var(--t-cap); }
.key { display: inline-flex; align-items: center; gap: 6px; }
.kbar, .rmini { display: inline-block; width: 26px; height: 3px; border-radius: 2px; background: var(--panel-2); overflow: hidden; }
.kbar i { display: block; width: 60%; height: 100%; background: var(--accent); }
.rmini { height: 5px; } .rmini i { display: block; width: 70%; height: 100%; background: var(--dur); }
.wdot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); }

.filters { display: flex; align-items: end; gap: var(--s3); padding: 0 var(--s5) var(--s2); }
.filters label { display: flex; flex-direction: column; gap: 3px; color: var(--muted); font-size: var(--t-cap); }
.filters .grow { flex: 1; max-width: 360px; }
input[type=search], select, button {
  height: 30px; padding: 0 var(--s3); background: var(--panel); color: var(--text);
  border: 1px solid var(--line); border-radius: 6px; font: inherit;
}
select { min-width: 160px; }
button { cursor: pointer; }
button:hover, select:hover, input:hover { border-color: #3a475d; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.filters .check { flex-direction: row; align-items: center; height: 30px; color: var(--text); font-size: var(--t-table); }
.count { margin: 0 0 0 auto; height: 30px; display: flex; align-items: center; color: var(--muted); font-size: var(--t-cap); }

.layout { flex: none; height: max(620px, calc(100vh - 150px)); display: grid; grid-template-columns: minmax(0, 1fr) 420px; gap: var(--s3); padding: 0 var(--s5) var(--s3); }
.table-scroll { overflow: auto; background: var(--panel); border: 1px solid var(--line); border-radius: 8px; }
table { width: 100%; border-collapse: collapse; }
#board { table-layout: fixed; }
#board th:nth-child(1) { width: 54px; } #board th:nth-child(3) { width: 70px; } #board th:nth-child(4) { width: 62px; }
#board th:nth-child(5) { width: 68px; } #board th:nth-child(6) { width: 62px; } #board th:nth-child(7) { width: 92px; }
#board th:nth-child(8) { width: 114px; } #board th:nth-child(9) { width: 124px; } #board th:nth-child(10) { width: 80px; }
th { position: sticky; top: 0; z-index: 1; background: var(--panel-2); text-align: left; font-size: var(--t-cap); font-weight: 600; color: var(--muted); border-bottom: 1px solid var(--line); padding: 0; white-space: nowrap; }
th button { all: unset; box-sizing: border-box; display: flex; align-items: center; gap: 3px; width: 100%; padding: 8px 8px; white-space: nowrap; cursor: pointer; overflow: hidden; }
th.num button { justify-content: flex-end; }
th[data-key=age] button { white-space: normal; line-height: 1.15; text-align: right; }
th button:hover { color: var(--text); }
th[aria-sort=ascending] button, th[aria-sort=descending] button { color: var(--accent); }
th[aria-sort=ascending] .arr::after { content: "▲"; }
th[aria-sort=descending] .arr::after { content: "▼"; }
.arr::after { content: "⇅"; }
th[aria-sort=none] .arr { opacity: .45; }
.arr { font-size: 9px; width: 10px; flex: none; }
td { padding: 5px 8px; border-bottom: 1px solid var(--line-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: var(--t-table); }
td.num, th.num { text-align: right; font-family: var(--mono); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: #18202c; }
tbody tr.sel { background: rgba(240,184,74,.11); box-shadow: inset 3px 0 0 var(--accent); }
td.name { padding-top: 4px; padding-bottom: 4px; }
.nm { font-weight: 600; overflow: hidden; text-overflow: ellipsis; }
.nm .w { display: inline-block; width: 6px; height: 6px; margin-right: 6px; border-radius: 50%; background: var(--accent); vertical-align: 2px; }
.why { font-size: var(--t-cap); font-weight: 400; color: var(--muted); overflow: hidden; text-overflow: ellipsis; line-height: 1.35; }
td.muted { color: var(--muted); }
tbody tr.dim td { opacity: .55; }
tbody tr.dim:hover td, tbody tr.dim.sel td { opacity: .85; }
.nm { display: flex; align-items: center; justify-content: space-between; gap: 6px; }
.nmt { overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.sig { flex: none; padding: 0 6px; border-radius: 4px; font: 700 11px/16px var(--mono); letter-spacing: .06em; border: 1px solid currentColor; }
.sig-dig { color: var(--up); background: rgba(63,198,168,.14); }
.sig-watch { color: var(--accent); background: rgba(240,184,74,.1); }
.sig-pass { color: var(--muted); border-color: var(--line); }
.why { display: flex; gap: 4px; margin-top: 2px; }
.fc { flex: none; padding: 0 5px; border-radius: 9px; border: 1px solid var(--k); color: var(--k); font: 600 12px/16px -apple-system, "Segoe UI", Inter, Roboto, Arial, sans-serif; white-space: nowrap; }
.fc.none { --k: var(--muted); border-color: var(--line); }
.up { color: var(--up); } .down { color: var(--down); }
.val { color: var(--accent); font-weight: 600; overflow: visible; }
.mult { color: var(--text); }
.empty { padding: var(--s5); color: var(--muted); text-align: center; }

.vtop { display: flex; align-items: center; justify-content: flex-end; gap: 5px; }
.vnum { min-width: 46px; text-align: right; }
.chip { display: inline-block; padding: 0 6px; border: 1px solid var(--line); border-radius: 9px; background: var(--panel-2); color: var(--muted); font: 600 var(--t-cap)/16px var(--mono); }
.warn { color: var(--thin); font-size: var(--t-cap); line-height: 1; font-weight: 400; }
.ratio { height: 3px; margin-top: 3px; border-radius: 2px; background: var(--panel-2); overflow: hidden; }
.ratio i { display: block; height: 100%; background: var(--accent); opacity: .75; }
td.val { padding-top: 4px; padding-bottom: 4px; }
.rrow { display: flex; align-items: center; gap: 6px; justify-content: flex-end; }
.rbar { width: 44px; height: 6px; border-radius: 3px; background: var(--panel-2); overflow: hidden; }
.rbar i { display: block; height: 100%; background: var(--dur); }
.rbar.lo i { background: var(--down); } .rbar.mid i { background: var(--accent); } .rbar.hi i { background: var(--up); }
.rbar.lo + .rn { color: var(--down); } .rbar.hi + .rn { color: var(--up); }
.rn { min-width: 24px; text-align: right; }

/* detail */
.detail { overflow: auto; background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: var(--s4); }
.detail h2 { margin: 0; font-size: var(--t-title); line-height: 1.2; overflow-wrap: anywhere; min-width: 0; }
.detail h3 { margin: var(--s3) 0 6px; font-size: var(--t-cap); font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
.dhead { display: flex; align-items: center; flex-wrap: wrap; gap: 4px var(--s2); }
.badge { flex: none; padding: 1px 7px; border-radius: 9px; border: 1px solid var(--line); background: var(--panel-2); color: var(--accent); font-size: var(--t-cap); font-weight: 600; white-space: nowrap; }
.badge.rk { color: var(--muted); }
.sub { margin: 2px 0 0; color: var(--muted); font-size: var(--t-table); }
.big { display: flex; align-items: baseline; gap: var(--s2); margin-top: var(--s3); flex-wrap: wrap; }
.big .n { font: 700 28px/1.1 var(--mono); color: var(--accent); }
.big .l { color: var(--muted); font-size: var(--t-cap); }
.big .chip { align-self: center; color: var(--text); }
.big .rangeTxt { margin-left: auto; font: var(--t-cap) var(--mono); color: var(--muted); }
.whyline { margin: var(--s2) 0 0; padding: 6px var(--s3); border-left: 3px solid var(--accent); background: var(--panel-2); border-radius: 0 6px 6px 0; font-size: var(--t-table); }

.trace { display: flex; align-items: flex-start; flex-wrap: wrap; gap: 4px 1px; padding: var(--s2) 6px; background: var(--panel-2); border-radius: 6px; font-family: var(--mono); }
.term { display: flex; flex-direction: column; align-items: center; gap: 1px; padding: 3px 3px; border-bottom: 2px solid var(--k); }
.tl { font-size: var(--t-cap); color: var(--muted); }
.tn { font-size: 11px; color: var(--muted); white-space: nowrap; max-width: 64px; overflow: hidden; text-overflow: ellipsis; }
.tv { font-size: 15px; white-space: nowrap; color: var(--k); }
.op { color: var(--muted); font-size: 13px; padding-top: 16px; width: 10px; text-align: center; }
.factors { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--s2); margin-top: var(--s2); }
.fac { background: var(--panel-2); border-radius: 6px; padding: 6px var(--s2); border-top: 3px solid var(--k); min-width: 0; }
.fac .k { font-size: var(--t-cap); color: var(--muted); }
.fac .v { font: 700 16px var(--mono); color: var(--k); }
.fac .why { margin-top: 2px; font-size: var(--t-cap); line-height: 1.3; color: var(--muted); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.band { margin-top: var(--s2); }
.band .bar { position: relative; height: 8px; border-radius: 4px; background: var(--panel-2); }
.band .rng { position: absolute; inset: 0; border-radius: 4px; background: linear-gradient(90deg, rgba(240,184,74,.2), rgba(240,184,74,.7), rgba(240,184,74,.2)); }
.band .mid { position: absolute; top: -3px; width: 2px; height: 14px; background: var(--text); }
.band .lab { display: flex; justify-content: space-between; margin-top: var(--s1); font: var(--t-cap) var(--mono); color: var(--muted); }

.rhead { display: flex; align-items: baseline; gap: 6px; margin-bottom: 6px; }
.rscore { font: 700 26px/1 var(--mono); }
.rof { color: var(--muted); font-size: var(--t-table); }
.rseg { display: flex; gap: 4px; }
.seg { min-width: 0; }
.track { height: 8px; border-radius: 4px; background: var(--panel-2); overflow: hidden; }
.track i { display: block; height: 100%; background: var(--k); }
.sl { margin-top: 4px; font: 600 var(--t-cap)/1.25 var(--mono); color: var(--k); overflow-wrap: anywhere; }
.sn { font-size: var(--t-cap); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.farm { width: 100%; table-layout: fixed; }
.farm th { position: static; padding: 5px var(--s2); font-size: var(--t-cap); }
.farm th:nth-child(2) { width: 132px; } .farm th:nth-child(3) { width: 66px; } .farm th:nth-child(4) { width: 48px; }
.farm td { padding: 5px var(--s2); white-space: normal; overflow: visible; text-overflow: clip; vertical-align: top; line-height: 1.35; font-size: var(--t-cap); }
.farm td.a { font-size: var(--t-cap); color: var(--text); }
.farm td.c, .farm td.t { font-family: var(--mono); text-align: right; } .farm td.t { white-space: nowrap; }
.farm th.num { text-align: right; }
.farm td.rk, .farm th.rk { text-align: center; }
.farm tfoot td { font-weight: 600; border-bottom: 0; }
.pill { display: inline-block; min-width: 34px; padding: 0 6px; border-radius: 9px; font-size: var(--t-cap); font-weight: 600; line-height: 16px; text-align: center; cursor: help; }
.pill.low { color: var(--up); background: rgba(63,198,168,.13); }
.pill.med { color: var(--accent); background: rgba(240,184,74,.14); }
.pill.high { color: var(--down); background: rgba(239,125,112,.15); }
.risknote { display: flex; flex-direction: column; gap: 2px; margin-top: var(--s3); padding: var(--s2) var(--s3); border: 1px solid rgba(239,125,112,.35); border-radius: 6px; background: rgba(239,125,112,.06); font-size: var(--t-cap); line-height: 1.4; }
.risknote b { color: var(--down); text-transform: uppercase; letter-spacing: .08em; }

.hint { color: var(--muted); }
.hint h2 { color: var(--text); white-space: normal; }
.lead { margin: var(--s2) 0 0; line-height: 1.45; }
.rule { display: flex; gap: var(--s2); margin: 6px 0 0; padding-left: var(--s2); border-left: 3px solid var(--k); font-size: var(--t-cap); line-height: 1.4; }
.rule b { color: var(--k); min-width: 52px; }

@media (max-width: 1100px) {
  .layout { grid-template-columns: 1fr; }
  .strip { grid-template-columns: repeat(2, 1fr); }
  .filters { flex-wrap: wrap; }
}

.rmini.lo i { background: var(--down); width: 100%; } .rmini.mid i { background: var(--accent); width: 100%; } .rmini.hi i { background: var(--up); width: 100%; }
.chip.conf { color: var(--thin); border-color: var(--thin); }

/* radar-5 */
.strip { align-items: stretch; }
.stat { flex-direction: column; align-items: flex-start; gap: 1px; padding: 6px var(--s3); }
.stat .sv { font-size: 22px; color: #ffd27a; }
.stat .sc { margin-left: 0; max-width: 100%; }
.vchip { display: inline-block; padding: 0 8px; border-radius: 4px; font: 700 12px/18px var(--mono); letter-spacing: .06em; border: 1px solid currentColor; }
.v-farm { color: var(--up); background: rgba(63,198,168,.14); }
.v-watch { color: var(--accent); background: rgba(240,184,74,.1); }
.v-skip { color: var(--muted); border-color: var(--line); }
td .l1 { font-weight: 600; } td .l2, .name .l2 { font: 400 11px/1.3 var(--mono); color: var(--muted); overflow: hidden; text-overflow: ellipsis; }
td.hr .l1 { color: var(--accent); } td.val .l1 { color: var(--text); }
.detail h3 { margin-top: var(--s4); }
.bottom { margin-top: var(--s3); padding: var(--s2) var(--s3); background: var(--panel-2); border-left: 3px solid var(--accent); border-radius: 0 6px 6px 0; }
.bottom .big { margin-top: 0; }
.big .n2 { font: 700 20px/1.1 var(--mono); color: var(--text); margin-left: var(--s3); }
.bottom .bl { margin: 4px 0 0; font-weight: 600; }
.calc { margin: 6px 0 0; color: var(--muted); font-size: var(--t-cap); line-height: 1.4; }
table.mini { width: 100%; table-layout: auto; }
.mini th { position: static; padding: 4px 6px; font-size: var(--t-cap); }
.mini td { padding: 3px 6px; font-size: var(--t-cap); white-space: normal; overflow: visible; vertical-align: top; line-height: 1.35; }
.mini td.num, .mini th.num { font-family: var(--mono); text-align: right; white-space: nowrap; }
.mini tfoot td { font-weight: 600; border-bottom: 0; }
.mini.farm td.num { white-space: normal; }
.mini.farm th:nth-child(2) { width: 120px; } .mini.farm th:nth-child(3) { width: 58px; } .mini.farm th:nth-child(4) { width: 62px; }
.mini.farm td:nth-child(3) { white-space: nowrap; }
.mini td.rk, .mini th.rk { text-align: center; }
.ln { display: flex; gap: var(--s2); font-size: var(--t-cap); line-height: 1.4; padding: 2px 0; border-bottom: 1px solid var(--line-2); }
.lk { flex: none; width: 74px; color: var(--muted); font-family: var(--mono); }
.lv { min-width: 0; overflow-wrap: anywhere; }
.layout { grid-template-columns: minmax(0, 1fr) 450px; }

.nm { justify-content: flex-start; }
.keys { margin-left: 0; }
.layout { grid-template-columns: minmax(0, 1fr) 420px; }
.bottom .big .n { font-size: 24px; } .bottom .big { flex-wrap: wrap; white-space: nowrap; } .big .n2 { font-size: 18px; }

.assume { margin: 2px 20px 8px; padding: 0; font-size: 13px; color: var(--muted, #8b95a5); font-variant-numeric: tabular-nums; }
.capmark { display: inline-block; padding: 0 5px; border-radius: 4px; border: 1px solid currentColor; font-size: 9px; line-height: 14px; margin-right: 2px; text-transform: uppercase; letter-spacing: .04em; color: #d9a441; vertical-align: 1px; }

/* net-first board: support line, verdict reason, integrity view */
.support { margin: 0 0 6px; font: 600 var(--t-cap) var(--mono); color: var(--gro); }
.support.global { color: var(--thin); }
.support.category { color: var(--accent); }
.verdict-why b { color: var(--text); }
.iview { margin: 0 var(--s5) var(--s3); padding: var(--s4); background: var(--panel); border: 1px solid var(--line); border-radius: 8px; }
.iview h2 { margin: 0 0 var(--s2); font-size: var(--t-title); }
.iview h2:not(:first-child) { margin-top: var(--s4); }
.iv-row { display: grid; grid-template-columns: 190px 360px 1fr; gap: var(--s3); padding: 5px 0; border-top: 1px solid var(--line-2); align-items: baseline; }
.iv-k { color: var(--muted); font-size: var(--t-cap); text-transform: uppercase; letter-spacing: .06em; }
.iv-v { font: 700 var(--t-table) var(--mono); }
.iv-t { color: var(--muted); font-size: var(--t-cap); }
.sup-row { display: grid; grid-template-columns: 90px 420px 170px 1fr; gap: var(--s3); align-items: center; padding: 5px 0; }
.sup-k { font: 700 var(--t-table) var(--mono); }
.sup-bar { display: block; height: 14px; background: var(--panel-2); border-radius: 4px; overflow: hidden; }
.sup-fill { display: block; height: 100%; }
.sup-finest { background: var(--gro); } .sup-category { background: var(--accent); } .sup-global { background: var(--thin); }
.sup-n { font: var(--t-table) var(--mono); }
.sup-d { color: var(--muted); font-size: var(--t-cap); }
body.view-integrity .layout, body.view-integrity .filters, body.view-integrity .legend { display: none; }
.strip .stat .sv { font-size: 17px; white-space: nowrap; }
.strip .stat { padding: 5px 10px; }
.strip .sk { font-size: 11px; letter-spacing: .04em; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.strip .sc { overflow: hidden; text-overflow: ellipsis; }
.legend { padding: 4px var(--s3); }

/* validation-first header: six KPI cards, then the protocol accounting */
.kpis { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: var(--s2); margin: 0 var(--s5) var(--s2); }
.kpi { display: flex; flex-direction: column; gap: 4px; padding: var(--s3) var(--s3) var(--s3); background: var(--panel); border: 1px solid var(--line); border-radius: 8px; min-width: 0; }
.kpi .kk { font-size: 11px; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--muted); }
